    40          if (streamEvent.type === "toolcall_start") {
    41            animationArgs.start(contentIndex, part?.name ?? "");
    42          } else if (streamEvent.type === "toolcall_delta") {
    43            const html = animationArgs.delta(contentIndex, streamEvent.delta ?? "", part?.name);
