     1  import type { AgentEvent, AgentMessage } from "@earendil-works/pi-agent-core";
     2  import type { ConversationRuntime } from "./conversation-runtime";
     3  import { jsonSafe } from "./conversation-runtime";
     4  
     5  const messageIds = new WeakMap<object, string>();
     6  let messageCounter = 0;
     7  
     8  function messageId(message: AgentMessage): string {
     9  	if (!message || typeof message !== "object") return `message-${++messageCounter}`;
    10  	let id = messageIds.get(message);
    11  	if (!id) {
    12  		const candidate = message as { responseId?: unknown; toolCallId?: unknown; timestamp?: unknown };
    13  		id = String(candidate.responseId ?? candidate.toolCallId ?? `message-${candidate.timestamp ?? ++messageCounter}`);
    14  		messageIds.set(message, id);
    15  	}
    16  	return id;
    17  }
    18  
    19  function toolFailureMessage(result: unknown): string {
    20  	const content = (result as { content?: unknown })?.content;
    21  	if (Array.isArray(content)) {
    22  		const text = content
    23  			.map((part) => part && typeof part === "object" && (part as { type?: unknown }).type === "text"
    24  				? (part as { text?: unknown }).text
    25  				: "")
    26  			.filter((value): value is string => typeof value === "string" && value.trim().length > 0)
    27  			.join("
");
    28  		if (text) return text;
    29  	}
    30  	const details = (result as { details?: unknown })?.details;
    31  	if (details && typeof details === "object" && typeof (details as { message?: unknown }).message === "string") {
    32  		return (details as { message: string }).message;
    33  	}
    34  	return "Tool execution failed.";
    35  }
    36  
    37  export function recordAgentEvent(runtime: ConversationRuntime, event: AgentEvent): void {
    38  	switch (event.type) {
    39  		case "agent_start":
    40  			runtime.emit("run.started", { mode: "text" });
    41  			break;
    42  		case "message_update":
    43  			if (event.assistantMessageEvent.type === "text_delta") {
    44  				runtime.emit("text.delta", { messageId: messageId(event.message), role: "assistant", delta: event.assistantMessageEvent.delta });
    45  			}
    46  			break;
    47  		case "message_end":
    48  			runtime.emit("message.completed", { messageId: messageId(event.message) });
    49  			break;
    50  		case "tool_execution_start":
    51  			runtime.emit("tool.requested", { callId: event.toolCallId, name: event.toolName, arguments: jsonSafe(event.args) as Record<string, never> });
    52  			runtime.emit("tool.started", { callId: event.toolCallId });
    53  			break;
    54  		case "tool_execution_update":
    55  			runtime.emit("tool.progress", { callId: event.toolCallId, update: jsonSafe(event.partialResult) });
    56  			break;
    57  		case "tool_execution_end":
    58  			if (event.isError) runtime.emit("tool.failed", { callId: event.toolCallId, error: { code: "tool-error", message: toolFailureMessage(event.result) } });
    59  			else runtime.emit("tool.completed", { callId: event.toolCallId, result: jsonSafe(event.result) });
    60  			break;
    61  		case "agent_end":
    62  			runtime.emit("run.completed", { reason: "completed" });
    63  			break;
    64  	}
    65  }

