     1  import type { AgentMessage } from "@earendil-works/pi-agent-core";
     2  
     3  export const INTERRUPTED_RESPONSE_MESSAGE =
     4  	"The response was interrupted before it finished. Retry to generate it again.";
     5  
     6  type AssistantLike = AgentMessage & {
     7  	role?: unknown;
     8  	content?: unknown;
     9  	stopReason?: unknown;
    10  	errorMessage?: unknown;
    11  };
    12  
    13  function cloneMessage(message: AgentMessage): AgentMessage {
    14  	const content = (message as AssistantLike).content;
    15  	return {
    16  		...message,
    17  		...(Array.isArray(content)
    18  			? { content: content.map((part) => (part && typeof part === "object" ? { ...part } : part)) }
    19  			: {}),
    20  	} as AgentMessage;
    21  }
    22  
    23  export function isRetryableAssistantMessage(message: AgentMessage | undefined): boolean {
    24  	if (!message) return false;
    25  	const entry = message as AssistantLike;
    26  	return entry.role === "assistant" && (entry.stopReason === "error" || entry.stopReason === "aborted");
    27  }
    28  
    29  export function messagesForSessionSnapshot(
    30  	messages: AgentMessage[],
    31  	streamingMessage: AgentMessage | undefined,
    32  ): { messages: AgentMessage[]; interrupted: boolean } {
    33  	const stableMessages = messages.map(cloneMessage);
    34  	if (!streamingMessage || (streamingMessage as AssistantLike).role !== "assistant") {
    35  		return { messages: stableMessages, interrupted: false };
    36  	}
    37  
    38  	const interrupted = cloneMessage(streamingMessage) as AssistantLike;
    39  	interrupted.stopReason = "aborted";
    40  	interrupted.errorMessage = INTERRUPTED_RESPONSE_MESSAGE;
    41  	return {
    42  		messages: [...stableMessages, interrupted as AgentMessage],
    43  		interrupted: true,
    44  	};
    45  }
    46  
    47  export function prepareMessagesForRetry(messages: AgentMessage[]): AgentMessage[] | null {
    48  	if (!isRetryableAssistantMessage(messages.at(-1))) return null;
    49  	const remaining = messages.slice(0, -1).map(cloneMessage);
    50  	const hasUserTurn = remaining.some((message) => {
    51  		const role = (message as { role?: unknown }).role;
    52  		return role === "user" || role === "user-with-attachments";
    53  	});
    54  	return hasUserTurn ? remaining : null;
    55  }

