    10  export function cloneMessages(messages: AgentMessage[]): AgentMessage[] {
    11  	return structuredClone(messages);
    12  }
    13  
    14  // Truncate a stored message list to end at the forked assistant turn. `forkPoint`
    15  // is the timestamp of the clicked assistant message (encoded in its rendered id).
    16  // We keep everything up to and including that assistant message plus the tool
    17  // results that belong to its turn, and drop the next user message onward — giving
    18  // a clean, continuable branch point. If nothing matches, the full list is kept.
    19  export function truncateAtForkPoint(
    20  	messages: AgentMessage[],
    21  	forkPoint: number | undefined,
    22  ): AgentMessage[] {
    23  	if (forkPoint == null) return messages;
    24  	let assistantIdx = -1;
    25  	for (let i = 0; i < messages.length; i++) {
    26  		const msg = messages[i] as { role?: string; timestamp?: number };
    27  		if (msg.role === "assistant" && msg.timestamp === forkPoint) assistantIdx = i;
    28  	}
    29  	if (assistantIdx === -1) return messages;
    30  	let boundary = messages.length;
    31  	for (let i = assistantIdx + 1; i < messages.length; i++) {
    32  		if ((messages[i] as { role?: string }).role === "user") {
    33  			boundary = i;
    34  			break;
    35  		}
    36  	}
    37  	return messages.slice(0, boundary);
    38  }
