    97  		usage.cost.cacheRead += messageUsage.cost?.cacheRead ?? 0;
    98  		usage.cost.cacheWrite += messageUsage.cost?.cacheWrite ?? 0;
    99  		usage.cost.total += messageUsage.cost?.total ?? 0;
   100  		return usage;
