// Compatibility exports for existing integrations and tests. New routing should
// prefer applyProviderWebSearch so capability negotiation stays centralized.
export { applyGoogleSearchGrounding, applyProviderWebSearch };
import { getProviderApiKey } from "../lib/provider-models";
import { localModel, getModelName, getModelId } from "../stores/local-model";

export const DEFAULT_MODEL = NOTORGANIC_DEFAULT_MODEL;

export function withProviderWebSearch(
	options: SimpleStreamOptions | undefined,
	model: Model<Api>,
	hasApiKey: boolean,
): SimpleStreamOptions | undefined {
	if (model.provider !== "google" && model.provider !== "openai" && model.provider !== "anthropic") {
		return options;
	}
	let signalled = false;

	return {
		...options,
		onPayload: async (payload, payloadModel) => {
			const userPayload = await options?.onPayload?.(payload, payloadModel);
			const nextPayload = userPayload ?? payload;
			const groundedPayload = applyProviderWebSearch(nextPayload, payloadModel, hasApiKey);
			if (groundedPayload !== undefined && !signalled) {
				signalled = true;
				signalHostedSearchActivation(resolveProviderWebSearchRoute(payloadModel, hasApiKey));
			}
			return groundedPayload ?? userPayload;
		},
	};
}

function createBrowserStreamFn() {
	return async (_model: Model<Api>, context: Context, options?: SimpleStreamOptions) => {
		const stream = createAssistantMessageEventStream();
		const abortSignal = options?.signal;

		const defaultFields = {
			api: "browser" as const,
			provider: "browser" as const,
			model: getModelId(),
			usage: {
				input: 0,
				output: 0,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 0,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
		};

		(async () => {
			try {
				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				const userMessages = context.messages
					.filter((m): m is Extract<typeof m, { role: "user" }> => m.role === "user")
					.map((m) => {
						const content = m.content;
						if (typeof content === "string") return content;
						return content
							.filter((c): c is Extract<typeof c, { type: "text" }> => c.type === "text")
							.map((c) => c.text)
							.join("\n");
					});

				const systemPrompt = context.systemPrompt || "";
				const conversationHistory = userMessages.join("\n\n");
				const fullPrompt = systemPrompt
					? `${systemPrompt}\n\n${conversationHistory}`
					: conversationHistory;

				const partialMessage: AssistantMessage = {
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: "" }],
					stopReason: "stop",
					timestamp: Date.now(),
				};

				stream.push({ type: "start", partial: partialMessage });
				stream.push({ type: "text_start", contentIndex: 0, partial: partialMessage });

				const response = await localModel.generate(
					fullPrompt,
					{ max_length: options?.maxTokens ?? 1024, temperature: options?.temperature ?? 0.7 },
					(token: string) => {
						const textBlock = partialMessage.content[0];
						if (textBlock.type === "text") textBlock.text += token;
						stream.push({ type: "text_delta", contentIndex: 0, delta: token, partial: partialMessage });
					},
				);

				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [{ type: "text", text: response }],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				stream.push({
					type: "text_end",
					contentIndex: 0,
					content: response,
					partial: partialMessage,
				});
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: response }],
					stopReason: "stop",
					timestamp: Date.now(),
				} as AssistantMessage);
			} catch (error) {
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [],
					stopReason: "error",
					errorMessage: error instanceof Error ? error.message : String(error),
					timestamp: Date.now(),
				} as AssistantMessage);
			}
		})();

		return stream;
	};
}

export async function hybridStreamFn(model: Model<Api>, context: Context, options?: SimpleStreamOptions) {
	if (model.provider === "browser") {
		return normalizeToolCallStream(await createBrowserStreamFn()(model, context, options), context);
	}

	const apiKey = options?.apiKey ?? await getProviderApiKey(model.provider);
	let streamOptions: SimpleStreamOptions | undefined = apiKey ? { ...options, apiKey } : options;
	if (isNotOrganicProvider(model.provider)) {
		streamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"idempotency-key": `keating_${crypto.randomUUID()}`,
			},
		};
	}

	if (shouldProxyModel(model)) {
		const proxiedModel = {
			...model,
			baseUrl: chatProxyBaseUrl(),
		};
		const proxiedOptions: SimpleStreamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"x-target-url": proxyTargetHeader(model.baseUrl),
			},
		};
		if (import.meta.env.DEV) {
			const hasApiKey = !!proxiedOptions.apiKey;
			console.log(`[keating:stream] proxy ${model.provider} -> ${model.baseUrl} (apiKey=${hasApiKey})`);
		}
		const mergedOptions = withProviderWebSearch(proxiedOptions, proxiedModel, !!apiKey);
		return normalizeToolCallStream(
			streamWithApiRetry(proxiedModel, context, mergedOptions, (nextOptions) => streamSimple(proxiedModel, context, nextOptions)),
			context,
		);
	}

	const mergedOptions = withProviderWebSearch(streamOptions, model, !!apiKey);
	return normalizeToolCallStream(
		streamWithApiRetry(model, context, mergedOptions, (nextOptions) => streamSimple(model, context, nextOptions)),
		context,
	);
}

import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type AssistantMessageEvent,
	type AssistantMessageEventStream,
	type Context,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai";
import {
	classifyLlmError,
	DEFAULT_API_RETRY_POLICY,
	isRetryableApiError,
	retryDelayMs,
	type ApiRetryPolicy,
} from "../core/api-retry.js";

export {
	classifyLlmError,
	isRetryableApiError,
	retryAfterDelayMs,
	retryDelayMs,
	retryableStatusCode,
	type ApiRetryPolicy,
	type LlmErrorCategory,
	type LlmErrorDetails,
} from "../core/api-retry.js";

export const WEB_API_RETRY_POLICY: ApiRetryPolicy = DEFAULT_API_RETRY_POLICY;

let nextStartAt = 0;

function errorText(error: unknown): string {
	if (error instanceof Error) return error.message;
	if (typeof error === "string") return error;
	try {
		return JSON.stringify(error);
	} catch {
		return String(error);
	}
}

function defaultUsage(): AssistantMessage["usage"] {
	return {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 0,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	};
}

function errorMessage(model: Model<Api>, error: unknown): AssistantMessage {
	return {
		role: "assistant",
		content: [],
		api: model.api,
		provider: model.provider,
		model: model.id,
		usage: defaultUsage(),
		stopReason: "error",
		errorMessage: errorText(error),
		timestamp: Date.now(),
	};
}

async function sleep(ms: number, signal?: AbortSignal): Promise<void> {
	if (ms <= 0) return;
	if (signal?.aborted) throw new Error("Request aborted");
	await new Promise<void>((resolve, reject) => {
		let timeout: ReturnType<typeof globalThis.setTimeout>;
		const cleanup = () => {
			globalThis.clearTimeout(timeout);
			signal?.removeEventListener("abort", abort);
		};
		const done = () => {
			cleanup();
			resolve();
		};
		const abort = () => {
			cleanup();
			reject(new Error("Request aborted"));
		};
		timeout = globalThis.setTimeout(done, ms);
		signal?.addEventListener("abort", abort, { once: true });
	});
}

async function waitForApiTurn(policy: ApiRetryPolicy, signal?: AbortSignal): Promise<void> {
	const now = Date.now();
	const waitMs = Math.max(0, nextStartAt - now);
	nextStartAt = Math.max(now, nextStartAt) + policy.rateLimitIntervalMs;
	await sleep(waitMs, signal);
}

export async function withApiRetry<T>(
	operation: () => Promise<T> | T,
	options: { policy?: ApiRetryPolicy; signal?: AbortSignal } = {},
): Promise<T> {
	const policy = options.policy ?? WEB_API_RETRY_POLICY;
	let lastError: unknown;

	for (let attempt = 0; attempt < policy.maxAttempts; attempt += 1) {
		await waitForApiTurn(policy, options.signal);
		try {
			return await operation();
		} catch (error) {
			lastError = error;
			if (attempt >= policy.maxAttempts - 1 || !isRetryableApiError(error)) throw error;
			await sleep(retryDelayMs(attempt, error, policy), options.signal);
		}
	}

	throw lastError;
}

function terminalErrorEvent(model: Model<Api>, error: unknown): AssistantMessageEvent {
	const message = errorMessage(model, error);
	return { type: "error", reason: "error", error: message };
}

function forwardBuffered(target: AssistantMessageEventStream, pending: AssistantMessageEvent[]): void {
	for (const event of pending) target.push(event);
	pending.length = 0;
}

function commitsAttempt(event: AssistantMessageEvent): boolean {
	if (event.type === "text_delta" || event.type === "thinking_delta") return event.delta.length > 0;
	return event.type === "toolcall_end" || event.type === "done";
}

type RetryAnnotatedMessage = AssistantMessage & {
	__keatingRetryAttempts?: number;
	__keatingRetryExhausted?: boolean;
};

function annotateRetryOutcome(
	message: AssistantMessage,
	attempts: number,
	exhausted: boolean,
): AssistantMessage {
	const annotated = message as RetryAnnotatedMessage;
	annotated.__keatingRetryAttempts = attempts;
	annotated.__keatingRetryExhausted = exhausted;
	return annotated;
}

export function streamWithApiRetry(
	model: Model<Api>,
	context: Context,
	options: SimpleStreamOptions | undefined,
	createStream: (options?: SimpleStreamOptions) => AssistantMessageEventStream,
	policy: ApiRetryPolicy = WEB_API_RETRY_POLICY,
): AssistantMessageEventStream {
	const target = createAssistantMessageEventStream();

	(async () => {
		let finalError: unknown;
		for (let attempt = 0; attempt < policy.maxAttempts; attempt += 1) {
			const pending: AssistantMessageEvent[] = [];
			let forwarded = false;
			let attemptError: AssistantMessage | null = null;

			try {
				await waitForApiTurn(policy, options?.signal);
				const source = createStream({
					...options,
					maxRetries: options?.maxRetries ?? 0,
					maxRetryDelayMs: options?.maxRetryDelayMs ?? policy.maxDelayMs,
				});

				for await (const event of source) {
					if (event.type === "error") {
						attemptError = event.error;
						break;
					}

					if (!forwarded) {
						pending.push(event);
						if (!commitsAttempt(event)) continue;
						forwardBuffered(target, pending);
						forwarded = true;
						continue;
					}
					target.push(event);
				}
			} catch (error) {
				attemptError = errorMessage(model, error);
			}

			if (!attemptError) return;
			finalError = attemptError.errorMessage ?? "API request failed";

